/** Kennung aus dem Namen: klein, ohne Umlaute und Sonderzeichen. */
export function kennung(name) {
  return String(name).toLocaleLowerCase("de").replace(/ä/g, "ae").replace(/ö/g, "oe").replace(/ü/g, "ue").replace(/ß/g, "ss")
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "").replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
}

export const KARTE_BREITE = 2000;
export const KARTE_HOEHE = 1417;
export const TYPEN = { region: "Land / Region", landschaft: "Landschaft (Gebirge, Wüste, Wald …)", meer: "Meer / Gewässer", insel: "Insel", fluss: "Fluss", ort: "Stadt / Ort", zusatz: "Zusatzbeschriftung" };
const ART = { region: "Land", landschaft: "Landschaft", meer: "Meer", insel: "Insel", fluss: "Fluss", ort: "Ort", zusatz: "" };
export const standardArt = (typ) => ART[typ] ?? "";

/** Ausgangsstand als Liste von Orten (frische Kopie mit allen Feldern). */
export function standardOrte() {
  return ORTE.map((o) => ({ drehung: 0, anzeige: "", art: "", groesse: 1, text: "", quelle: "", allen: false, pruefen: false, ergaenzt: false,
    geruecht: GERUECHTE[o.id]?.[1] ?? "", geruechtWahr: GERUECHTE[o.id]?.[0] ?? "", ...o }));
}

