/** Bildkategorie eines Ortes (für bilder/karte/kategorie/<kategorie>.webp). */
export function bildKategorie(o) {
  if (o.bildKategorie) return o.bildKategorie;
  if (NACH_ID[o.id]) return NACH_ID[o.id];
  switch (o.typ) {
    case "ort": {
      const land = (o.art ?? "").match(/ in ([^(]+?)(?: \(|$)/)?.[1]?.trim() ?? (/Valian/.test(o.art ?? "") ? "Valian" : "");
      return STADT_KULTUR[land] ?? "stadt-vesternesse";
    }
    case "region": return LAND_BILD[o.id] ?? `land-${o.id}`;
    case "insel": return LAND_BILD[o.id] ?? "insel-tropisch";
    case "meer": return "meer-tropisch";
    case "fluss": return "fluss-gemaessigt";
    case "landschaft": return /Gebirge/.test(o.art ?? "") ? "gebirge-mittel" : "grasebene";
    default: return "";
  }
}
